ext-white ms-2\">Item {{ currentItem.order }} di {{ progress.total }}</small>\r\n        </div>\r\n        <div class=\"btn-group btn-group-sm\">\r\n          <button class=\"btn btn-light\" (click)=\"previous()\" [disabled]=\"currentItemIndex === 0\">\r\n            <i class=\"fas fa-chevron-left\"></i>\r\n          </button>\r\n          <button class=\"btn btn-light\" (click)=\"next()\" [disabled]=\"!getResponse(currentItem.code)\">\r\n            <i class=\"fas fa-chevron-right\"></i>\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n    <div class=\"card-body p-4\">\r\n      <div class=\"mb-4\">\r\n        <h4 class=\"card-title fw-bold\">{{ currentItem.text }}</h4>\r\n        <small class=\"text-muted\"><i class=\"fas fa-tag me-1\"></i>Dominio: {{ currentItem.domainLabel }}</small>\r\n      </div>\r\n\r\n      <!-- Scale Buttons -->\r\n      <div class=\"row g-2\">\r\n        <div *ngFor=\"let scale of getScaleLabels()\" class=\"col-lg-6\">\r\n          <button type=\"button\"\r\n                  class=\"btn btn-lg w-100 text-start p-2 border-3 rounded-3 shadow-sm transition-all\"\r\n                  [class]=\"scale.class + ' ' + (getResponse(currentItem.code) === scale.value ? 'fw-bold border-primary shadow-lg' : '')\"\r\n                  (click)=\"onScoreSelect(scale.value)\"\r\n                  [attr.aria-pressed]=\"getResponse(currentItem.code) === scale.value\"\r\n                  style=\"min-height: 60px;\">\r\n            <div class=\"d-flex justify-content-between align-items-center\">\r\n              <div>\r\n                <div class=\"fw-bold fs-6\">{{ scale.label }}</div>\r\n                <small class=\"opacity-75\">Punteggio: {{ scale.value }}</small>\r\n              </div>\r\n              <i class=\"fas fa-check-circle fa-2x\" *ngIf=\"getResponse(currentItem.code) === scale.value\"></i>\r\n            </div>\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Quick navigation -->\r\n      <div class=\"mt-4 pt-3 border-top\">\r\n        <small class=\"text-muted d-block mb-2\"><i class=\"fas fa-magic me-1\"></i>Navigazione rapida:</small>\r\n        <div class=\"d-flex flex-wrap gap-1\">\r\n          <button *ngFor=\"let item of getAllItems()\"\r\n                  type=\"button\"\r\n                  class=\"btn btn-sm px-3 py-2 rounded-pill\"\r\n                  [class.btn-primary]=\"isItemCurrent(item.code)\"\r\n                  [class.btn-success]=\"isItemAnswered(item.code) && !isItemCurrent(item.code)\"\r\n                  [class.btn-outline-secondary]=\"!isItemAnswered(item.code) && !isItemCurrent(item.code)\"\r\n                  (click)=\"goToItem(item.order - 1)\"\r\n                  [title]=\"item.text.substring(0, 50) + '...'\">\r\n            {{ item.order }}\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Results View -->\r\n  <div class=\"card shadow-lg border-0\" *ngIf=\"showResults && assessmentResult\">\r\n    <div class=\"card-header bg-gradient-success text-white py-3\">\r\n      <h4 class=\"mb-0\"><i class=\"fas fa-chart-line me-2\"></i>Risultati Valutazione WHODAS 2.0</h4>\r\n    </div>\r\n    <div class=\"card-body p-4\">\r\n      <!-- Overall Scores -->\r\n      <div class=\"row g-3 mb-4\">\r\n        <div class=\"col-md-4\">\r\n          <div class=\"card bg-primary text-white h-100\">\r\n            <div class=\"card-body text-center py-4\">\r\n              <h1 class=\"mb-0 display-4 fw-bold\">{{ (assessmentResult.overallSimpleScore | ceilValue) }}</h1>\r\n              <small class=\"fs-6\">Punteggio Semplice (somma)</small>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"col-md-4\">\r\n          <div class=\"card bg-info text-white h-100\">\r\n            <div class=\"card-body text-center py-4\">\r\n              <h1 class=\"mb-0 display-4 fw-bold\">{{ (assessmentResult.overallComplexScore | ceilValue) }}%</h1>\r\n              <small class=\"fs-6\">Punteggio Complesso (0-100)</small>\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"col-md-4\">\r\n          <div class=\"card bg-warning text-white h-100\">\r\n            <div class=\"card-body text-center py-4\">\r\n              <h1 class=\"mb-0 display-4 fw-bold\">{{ (assessmentResult.overallPercentDisability | ceilValue) }}%</h1>\r\n              <small class=\"fs-6\">Disabilit\u00E0 %</small>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Domain Scores Cards -->\r\n      <h5 class=\"mb-3\"><i class=\"fas fa-chart-bar me-2 text-primary\"></i>Punteggi per Dominio</h5>\r\n      <div class=\"row g-3 mb-4\">\r\n        <div *ngFor=\"let d of domainScores\" class=\"col-xl-4 col-lg-6\">\r\n          <div class=\"card h-100 border-0 shadow-sm\" [class.border-success]=\"d.percentDisability < 25\" [class.border-warning]=\"d.percentDisability >= 25 && d.percentDisability < 50\" [class.border-orange]=\"d.percentDisability >= 50 && d.percentDisability < 75\" [class.border-danger]=\"d.percentDisability >= 75\" style=\"border-width: 3px !important;\">\r\n            <div class=\"card-body p-3\">\r\n              <div class=\"d-flex justify-content-between align-items-start mb-2\">\r\n                <div>\r\n                  <h6 class=\"mb-0 fw-bold fs-5\">{{ d.domainLabel }}</h6>\r\n                  <small class=\"text-muted\">({{ d.domain }})</small>\r\n                </div>\r\n                <span class=\"badge fs-6 px-3 py-2\" [class.bg-success]=\"d.percentDisability < 25\" [class.bg-warning]=\"d.percentDisability >= 25 && d.percentDisability < 50\" [class.bg-orange]=\"d.percentDisability >= 50 && d.percentDisability < 75\" [class.bg-danger]=\"d.percentDisability >= 75\">\r\n                  {{ (d.percentDisability | ceilValue) }}%\r\n                </span>\r\n              </div>\r\n              <div class=\"row text-center g-0\">\r\n                <div class=\"col-4 border-end\">\r\n                  <div class=\"fs-6 text-muted mb-1\">Item</div>\r\n                  <div class=\"fw-bold fs-5\">{{ d.itemCount }}</div>\r\n                </div>\r\n                <div class=\"col-4 border-end\">\r\n                  <div class=\"fs-6 text-muted mb-1\">Punt. Grezzo</div>\r\n                  <div class=\"fw-bold fs-5\">{{ (d.rawScore | ceilValue) }}</div>\r\n                </div>\r\n                <div class=\"col-4\">\r\n                  <div class=\"fs-6 text-muted mb-1\">Media</div>\r\n                  <div class=\"fw-bold fs-5\">{{ (d.averageScore | ceilValue) }}</div>\r\n                </div>\r\n              </div>\r\n              <div class=\"row text-center mt-2 pt-2 border-top\">\r\n                <div class=\"col-6 border-end\">\r\n                  <div class=\"fs-6 text-muted mb-1\">Semplice</div>\r\n                  <div class=\"fw-bold fs-5 text-primary\">{{ (d.simpleScore | ceilValue) }}</div>\r\n                </div>\r\n                <div class=\"col-6\">\r\n                  <div class=\"fs-6 text-muted mb-1\">Complesso</div>\r\n                  <div class=\"fw-bold fs-5 text-info\">{{ (d.complexScore | ceilValue) }}%</div>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Interpretation -->\r\n      <div class=\"alert alert-info border-0 shadow-sm\">\r\n        <h6 class=\"alert-heading\"><i class=\"fas fa-info-circle me-2\"></i>Interpretazione</h6>\r\n        <p class=\"mb-2\">\r\n          <strong>0-4%:</strong> Nessuna disabilit\u00E0 |\r\n          <strong>5-24%:</strong> Disabilit\u00E0 lieve |\r\n          <strong>25-49%:</strong> Disabilit\u00E0 moderata |\r\n          <strong>50-74%:</strong> Disabilit\u00E0 grave |\r\n          <strong>75-100%:</strong> Disabilit\u00E0 estrema\r\n        </p>\r\n        <p class=\"mb-0\"><strong>Disabilit\u00E0 complessiva:</strong> {{ getDisabilityLevel(assessmentResult.overallPercentDisability) }}</p>\r\n      </div>\r\n\r\n      <div class=\"d-flex gap-3 justify-content-center mt-4\">\r\n        <button class=\"btn btn-primary btn-lg px-5 py-3 shadow-sm\" (click)=\"onNewAssessment()\">\r\n          <i class=\"fas fa-plus me-2\"></i> Nuova Valutazione\r\n        </button>\r\n        <button class=\"btn btn-outline-secondary btn-lg px-5 py-3 shadow-sm\" (click)=\"onBackToPatients()\">\r\n          <i class=\"fas fa-arrow-left me-2\"></i> Torna ai Pazienti\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Completion Message -->\r\n  <div class=\"card shadow-lg border-0 text-center py-5\" *ngIf=\"isComplete && !showResults && !currentItem\">\r\n    <div class=\"card-body p-5\">\r\n      <i class=\"fas fa-check-circle fa-6x text-success mb-4\"></i>\r\n      <h2 class=\"mb-3\">Questionario Completato!</h2>\r\n      <p class=\"text-muted mb-4 fs-5\">Tutte le domande hanno ricevuto una risposta.</p>\r\n      <button class=\"btn btn-success btn-lg px-5 py-3 shadow-sm\" (click)=\"onComplete()\">\r\n        <i class=\"fas fa-save me-2\"></i> Calcola Punteggi e Salva\r\n      </button>\r\n    </div>\r\n  </div>\r\n</div>",
